SELECT pname as 参数名称, instance_name as 实例名称, param_value as 参数值
  FROM (SELECT DECODE(p.isdefault,'FALSE',SUBSTR(p.name, 0, 512),SUBSTR(p.name, 0, 512)) pname,
               DECODE(p.isdefault, 'FALSE', i.instance_name, i.instance_name) instance_name,
               DECODE(p.isdefault,'FALSE',SUBSTR(p.value, 0, 512),SUBSTR(p.value, 0, 512)) param_value
          FROM gv$parameter p, gv$instance i
         WHERE p.inst_id = i.inst_id
           AND p.name in ('shared_pool_size',
                          'open_cursors',
                          'processes',
                          'job_queue_processes',
                          'sga_max_size',
                          'log_archive_dest_1',
                          'sessions',
                          'spfile',
                          'cpu_count',
                          'sga_target',
                          'db_cache_size',
                          'shared_pool_size',
                          'large_pool_size',
                          'java_pool_size',
                          'log_buffer',
                          'pga_aggregate_target',
                          'sort_area_size',
                          'db_block_size',
                          'optimizer_mode',
                          'cursor_sharing',
                          'open_cursors',
                          'optimizer_index_cost_adj',
                          'optimizer_index_caching',
                          'db_file_multiblock_read_count',
                          'hash_join_enabled',
                          'thread',
                          'instance_number',
                          'instance_name',
                          'local_listener',
                          'compatible',
                          'commit_point_strength',
                          'dblink_encrypt_login',
                          'distributed_lock_timeout',
                          'distributed_recovery_connection_hold_time',
                          'distributed_transactions',
                          'global_names',
                          'job_queue_interval',
                          'job_queue_processes',
                          'max_transaction_branches',
                          'open_links',
                          'open_links_per_instance',
                          'parallel_automatic_tuning',
                          'parallel_max_servers',
                          'parallel_min_servers',
                          'parallel_server_idle_time',
                          'processes',
                          'remote_dependencies_mode',
                          'replication_dependency_tracking',
                          'shared_pool_size',
                          'utl_file_dir',
                          'db_create_file_dest')
         ORDER BY p.name, i.instance_name) A;
